  "settings.modelProvider.help.contextWindow":
    "La capacidad de contexto que el modelo puede procesar de una vez, en tokens. ZCode la usa para gestionar el contexto.\nNo superes el límite real del modelo.",
  "settings.modelProvider.help.maxOutputTokens":
    "El número máximo de tokens que puede generar una sola solicitud al modelo.\nNo superes el límite real del modelo.",
  "settings.modelProvider.help.inputModalities":
    "Define los tipos de contenido que puede recibir el modelo:\n\n- **Texto**: recibe contenido de texto. Obligatorio.\n- **Imágenes**: recibe imágenes.\n- **Vídeo**: recibe vídeo.\n- **PDF**: recibe documentos PDF directamente.",
  "settings.modelProvider.help.outputModalities":
    "El tipo de contenido de las respuestas del modelo. Por ahora solo se admite texto.",
  "settings.modelProvider.help.capabilities":
    "- **Salida estructurada**: admite restricciones JSON Schema sobre los campos, tipos y estructura de la salida.\n- **Búsqueda web nativa**: admite la búsqueda web integrada en la API del modelo.\n- **Mensajes de sistema a mitad de conversación**: admite insertar instrucciones de sistema durante una conversación.\n\nNo actives capacidades que el modelo no admita.",
  "settings.modelProvider.help.reasoningLevelsOrdered":
    "Define los niveles de razonamiento disponibles en el chat. **Deben ordenarse del menor al mayor esfuerzo de razonamiento**.\nNo configures niveles de razonamiento que el modelo no admita.",
  "settings.modelProvider.help.reasoningLevelMapping":
    "Usa una expresión CEL para asignar el nivel de razonamiento actual, `reasoningLevel`, a campos de la solicitud a la API del modelo. El objeto JSON que devuelve la expresión se fusiona con el cuerpo de la solicitud saliente.",
  "settings.modelProvider.help.advanced":
    "**Esquema de herramientas MFJS**: activa la compatibilidad con Moonshot Flavored JSON Schema, que suele usar la API del modelo Kimi de Moonshot. Actívalo solo cuando la API del modelo exija este formato.",
  "settings.modelProvider.help.followRecommendedConfig":
    "Aplica la configuración recomendada según el ID del modelo, la URL base y el formato de API. ZCode actualiza continuamente las recomendaciones y te las sincroniza automáticamente.\nCuando cambias un ajuste manualmente, ese ajuste pasa a gestión manual y deja de seguir las recomendaciones; los demás siguen gestionados por la configuración inteligente.",
